//! Thin IPC facade of the catalogue's opening actions. Every command takes
//! opaque identifiers published by the catalogue, never a free path; the
//! work runs off the main thread.
use crate::{
    services::catalogue::{
        self,
        open::{self, consultation},
    },
    support::user_message::UserMessage,
};

/// Simulates an exemplar: revalidation, then a consultation isolated from any
/// project or work session. `consultationId` is the launch token generated by
/// the interface; closing it cancels the preparation.
#[tauri::command]
pub async fn catalogue_open_consultation(
    app: tauri::AppHandle,
    consultation_id: String,
    exemplar_id: String,
    expected_revision: i64,
    project_json: Option<String>,
) -> Result<consultation::ConsultationHandle, UserMessage> {
    tauri::async_runtime::spawn_blocking(move || {
        let registry = open::consultations(&app)?;
        let store = catalogue::open_store(&app)?;
        consultation::open(
            &registry,
            &store,
            consultation::Request {
                consultation_id: &consultation_id,
                exemplar_id: &exemplar_id,
                expected_revision,
                project_json: project_json.as_deref(),
            },
        )
    })
    .await
    .map_err(catalogue::store::error)?
}

/// Bytes of one media of a ready consultation (binary response; the media
/// type was published with the consultation).
#[tauri::command]
pub async fn catalogue_read_consultation_asset(
    app: tauri::AppHandle,
    consultation_id: String,
    media_id: String,
) -> Result<tauri::ipc::Response, UserMessage> {
    tauri::async_runtime::spawn_blocking(move || {
        let registry = open::consultations(&app)?;
        registry
            .read(&consultation_id, &media_id)
            .map(|(bytes, _)| tauri::ipc::Response::new(bytes))
    })
    .await
    .map_err(catalogue::store::error)?
}

/// Closes a consultation; idempotent.
#[tauri::command]
pub async fn catalogue_close_consultation(
    app: tauri::AppHandle,
    consultation_id: String,
) -> Result<consultation::Closed, UserMessage> {
    tauri::async_runtime::spawn_blocking(move || {
        let registry = open::consultations(&app)?;
        Ok(registry.close(&consultation_id))
    })
    .await
    .map_err(catalogue::store::error)?
}

#[tauri::command]
pub async fn catalogue_prepare_editor_entry(
    app: tauri::AppHandle,
    exemplar_id: String,
    expected_revision: i64,
    purpose: String,
) -> Result<open::editor_entry::EditorEntry, UserMessage> {
    tauri::async_runtime::spawn_blocking(move || {
        catalogue::open_store(&app)?.prepare_editor_entry(&exemplar_id, expected_revision, &purpose)
    })
    .await
    .map_err(catalogue::store::error)?
}

#[tauri::command]
pub async fn catalogue_record_generation(
    app: tauri::AppHandle,
    project_path: String,
    output_path: String,
    generated_project_json: Option<String>,
    generated_output_fingerprint: Option<String>,
) -> Result<open::generation::Recorded, UserMessage> {
    use tauri::Manager;
    tauri::async_runtime::spawn_blocking(move || {
        let store = catalogue::open_store(&app)?;
        // These callbacks only arrive after a successful generation. Native
        // writers declared the output before writing; acknowledge the final path.
        catalogue::writes::OwnWrite::begin(
            catalogue::writes::Declaration::new("generation-receipt").exact(&output_path),
        )
        .succeeded(vec![output_path.clone().into()]);
        let result = store.record_generation(
            std::path::Path::new(&project_path),
            std::path::Path::new(&output_path),
            &app.path()
                .app_cache_dir()
                .map_err(catalogue::store::error)?,
            &app.path().app_data_dir().map_err(catalogue::store::error)?,
            catalogue::writes::shared(),
            generated_project_json.as_deref(),
            generated_output_fingerprint.as_deref(),
        )?;
        if result.recorded {
            use tauri::Emitter;
            let revision: i64 =
                store.read(|c| c.query_row("SELECT revision FROM catalogue", [], |r| r.get(0)))?;
            let _ = app.emit(
                "catalogue-changed",
                serde_json::json!({"catalogueRevision":revision,"scope":"entries"}),
            );
        }
        Ok(result)
    })
    .await
    .map_err(catalogue::store::error)?
}

/// Releases all temporary inputs of a mounted editor funnel. Late extractions
/// are rejected; already-running native readers release their lease at return.
#[tauri::command]
pub async fn catalogue_release_editor_extractions(
    app: tauri::AppHandle,
    owner_id: String,
) -> Result<(), UserMessage> {
    tauri::async_runtime::spawn_blocking(move || {
        catalogue::open_store(&app)?;
        open::release_editor_extractions(&app, &owner_id)
    })
    .await
    .map_err(catalogue::store::error)?
}
